@Test
public void testBasicRunJobForSingleNodeTraining() throws Exception {
    RunJobCli runJobCli = new RunJobCli(RunJobCliParsingCommonTest.getMockClientContext());
    assertFalse(SubmarineLogs.isVerbose());
    runJobCli.run(new String[] { "--framework", "mxnet", "--name", "my-job", "--docker_image", "mxnet-docker:1.1.0", "--input_path", "hdfs://input", "--num_workers", "1", "--num_ps", "1", "--worker_launch_cmd", "python run-job.py", "--worker_resources", "memory=2048M,vcores=2", "--ps_resources", "memory=4G,vcores=2", "--ps_launch_cmd", "python run-ps.py", "--num_schedulers", "1", "--scheduler_launch_cmd", "python run-scheduler.py", "--scheduler_resources", "memory=1024M,vcores=2", "--verbose", "--wait_job_finish" });
    RunJobParameters jobRunParameters = runJobCli.getRunJobParameters();
    assertTrue(RunJobParameters.class + " must be an instance of " + MXNetRunJobParameters.class, jobRunParameters instanceof MXNetRunJobParameters);
    MXNetRunJobParameters mxNetParams = (MXNetRunJobParameters) jobRunParameters;
    assertEquals(jobRunParameters.getInputPath(), "hdfs://input");
    assertEquals(mxNetParams.getNumWorkers(), 1);
    assertEquals(mxNetParams.getWorkerLaunchCmd(), "python run-job.py");
    assertEquals(Resources.createResource(2048, 2), mxNetParams.getWorkerResource());
    assertEquals(mxNetParams.getNumPS(), 1);
    assertEquals(mxNetParams.getNumSchedulers(), 1);
    assertTrue(SubmarineLogs.isVerbose());
    assertTrue(jobRunParameters.isWaitJobFinish());
}

@Test
public void testBasicRunJobForDistributedTraining() throws Exception {
    RunJobCli runJobCli = new RunJobCli(RunJobCliParsingCommonTest.getMockClientContext());
    assertFalse(SubmarineLogs.isVerbose());
    runJobCli.run(new String[] { "--framework", "mxnet", "--name", "my-job", "--docker_image", "mxnet-docker:1.1.0", "--input_path", "hdfs://input", "--num_workers", "2", "--num_ps", "2", "--worker_launch_cmd", "python run-job.py", "--worker_resources", "memory=2048M,vcores=2", "--ps_resources", "memory=4G,vcores=2", "--ps_launch_cmd", "python run-ps.py", "--num_schedulers", "1", "--scheduler_launch_cmd", "python run-scheduler.py", "--scheduler_resources", "memory=1024M,vcores=2", "--verbose" });
    RunJobParameters jobRunParameters = runJobCli.getRunJobParameters();
    assertTrue(RunJobParameters.class + " must be an instance of " + MXNetRunJobParameters.class, jobRunParameters instanceof MXNetRunJobParameters);
    MXNetRunJobParameters mxNetParams = (MXNetRunJobParameters) jobRunParameters;
    assertEquals(jobRunParameters.getInputPath(), "hdfs://input");
    assertEquals(jobRunParameters.getDockerImageName(), "mxnet-docker:1.1.0");
    assertEquals(mxNetParams.getNumWorkers(), 2);
    assertEquals(Resources.createResource(2048, 2), mxNetParams.getWorkerResource());
    assertEquals(mxNetParams.getWorkerLaunchCmd(), "python run-job.py");
    assertEquals(mxNetParams.getNumPS(), 2);
    assertEquals(Resources.createResource(4096, 2), mxNetParams.getPsResource());
    assertEquals(mxNetParams.getPSLaunchCmd(), "python run-ps.py");
    assertEquals(mxNetParams.getNumSchedulers(), 1);
    assertEquals(Resources.createResource(1024, 2), mxNetParams.getSchedulerResource());
    assertEquals(mxNetParams.getSchedulerLaunchCmd(), "python run-scheduler.py");
    assertTrue(SubmarineLogs.isVerbose());
}

