@Test
public void testLaunchCommandPatternReplace() throws Exception {
    RunJobCli runJobCli = new RunJobCli(getMockClientContext());
    assertFalse(SubmarineLogs.isVerbose());
    List<String> parameters = Lists.newArrayList("--framework", getFrameworkName(), "--name", "my-job", "--docker_image", "tf-docker:1.1.0", "--input_path", "hdfs://input", "--checkpoint_path", "hdfs://output", "--num_workers", "3", "--worker_launch_cmd", "python run-job.py --input=%input_path% " + "--model_dir=%checkpoint_path% " + "--export_dir=%saved_model_path%/savedmodel", "--worker_resources", "memory=2048,vcores=2");
    if (framework == Framework.TENSORFLOW) {
        parameters.addAll(Lists.newArrayList("--ps_resources", "memory=4096,vcores=4", "--ps_launch_cmd", "python run-ps.py --input=%input_path% " + "--model_dir=%checkpoint_path%/model", "--verbose"));
    }
    runJobCli.run(parameters.toArray(new String[0]));
    RunJobParameters runJobParameters = checkExpectedFrameworkParams(runJobCli);
    if (framework == Framework.TENSORFLOW) {
        TensorFlowRunJobParameters tensorFlowParams = (TensorFlowRunJobParameters) runJobParameters;
        assertEquals("python run-job.py --input=hdfs://input --model_dir=hdfs://output " + "--export_dir=hdfs://output/savedmodel", tensorFlowParams.getWorkerLaunchCmd());
        assertEquals("python run-ps.py --input=hdfs://input " + "--model_dir=hdfs://output/model", tensorFlowParams.getPSLaunchCmd());
    } else if (framework == Framework.PYTORCH) {
        PyTorchRunJobParameters pyTorchParameters = (PyTorchRunJobParameters) runJobParameters;
        assertEquals("python run-job.py --input=hdfs://input --model_dir=hdfs://output " + "--export_dir=hdfs://output/savedmodel", pyTorchParameters.getWorkerLaunchCmd());
    }
}

