@Test
public void testValidPyTorchJobSpecWithEnv() throws IOException, URISyntaxException, InvalidSpecException {
    EnvironmentManager environmentManager = EnvironmentManager.getInstance();
    EnvironmentSpec spec = new EnvironmentSpec();
    String envName = "my-submarine-env";
    spec.setName(envName);
    String dockerImage = "example.com/my-docker-image:0.1.2";
    spec.setDockerImage(dockerImage);
    KernelSpec kernelSpec = new KernelSpec();
    String kernelName = "team_python";
    kernelSpec.setName(kernelName);
    List<String> channels = new ArrayList<String>();
    String channel = "default";
    channels.add(channel);
    kernelSpec.setChannels(channels);
    List<String> dependencies = new ArrayList<String>();
    String dependency = "_ipyw_jlab_nb_ext_conf=0.1.0=py37_0";
    dependencies.add(dependency);
    kernelSpec.setCondaDependencies(dependencies);
    spec.setKernelSpec(kernelSpec);
    environmentManager.createEnvironment(spec);
    ExperimentSpec jobSpec = (ExperimentSpec) buildFromJsonFile(ExperimentSpec.class, pytorchJobWithEnvReqFile);
    PyTorchJob pyTorchJob = (PyTorchJob) ExperimentSpecParser.parseJob(jobSpec);
    MLJobReplicaSpec mlJobReplicaSpec = pyTorchJob.getSpec().getReplicaSpecs().get(PyTorchJobReplicaType.Master);
    Assert.assertEquals(1, mlJobReplicaSpec.getTemplate().getSpec().getInitContainers().size());
    V1Container initContainer = mlJobReplicaSpec.getTemplate().getSpec().getInitContainers().get(0);
    Assert.assertEquals(dockerImage, initContainer.getImage());
    Assert.assertEquals("/bin/bash", initContainer.getCommand().get(0));
    Assert.assertEquals("-c", initContainer.getCommand().get(1));
    String minVersion = "minVersion=\"" + conf.getString(SubmarineConfVars.ConfVars.ENVIRONMENT_CONDA_MIN_VERSION) + "\";";
    String maxVersion = "maxVersion=\"" + conf.getString(SubmarineConfVars.ConfVars.ENVIRONMENT_CONDA_MAX_VERSION) + "\";";
    String currentVersion = "currentVersion=$(conda -V | cut -f2 -d' ');";
    Assert.assertEquals(minVersion + maxVersion + currentVersion + "if [ \"$(printf '%s\\n' \"$minVersion\" \"$maxVersion\" " + "\"$currentVersion\" | sort -V | head -n2 | tail -1 )\" " + "!= \"$currentVersion\" ]; then echo \"Conda version " + "should be between minVersion=\"4.0.1\"; " + "and maxVersion=\"4.10.10\";\"; exit 1; else echo " + "\"Conda current version is " + currentVersion + ". " + "Moving forward with env creation and activation.\"; " + "fi && " + "conda create -n " + kernelName + " -c " + channel + " " + dependency + " && " + "echo \"source activate " + kernelName + "\" > ~/.bashrc" + " && " + "PATH=/opt/conda/envs/env/bin:$PATH", initContainer.getCommand().get(2));
    environmentManager.deleteEnvironment(envName);
}

@Test
public void testValidPyTorchJobSpecWithHTTPGitCodeLocalizer() throws IOException, URISyntaxException, InvalidSpecException {
    ExperimentSpec jobSpec = (ExperimentSpec) buildFromJsonFile(ExperimentSpec.class, pytorchJobWithHTTPGitCodeLocalizerFile);
    PyTorchJob pyTorchJob = (PyTorchJob) ExperimentSpecParser.parseJob(jobSpec);
    MLJobReplicaSpec mlJobReplicaSpec = pyTorchJob.getSpec().getReplicaSpecs().get(PyTorchJobReplicaType.Master);
    Assert.assertEquals(1, mlJobReplicaSpec.getTemplate().getSpec().getInitContainers().size());
    V1Container initContainer = mlJobReplicaSpec.getTemplate().getSpec().getInitContainers().get(0);
    Assert.assertEquals(AbstractCodeLocalizer.CODE_LOCALIZER_INIT_CONTAINER_NAME, initContainer.getName());
    Assert.assertEquals(GitCodeLocalizer.GIT_SYNC_IMAGE, initContainer.getImage());
    Assert.assertEquals(AbstractCodeLocalizer.CODE_LOCALIZER_MOUNT_NAME, initContainer.getVolumeMounts().get(0).getName());
    Assert.assertEquals(AbstractCodeLocalizer.CODE_LOCALIZER_PATH, initContainer.getVolumeMounts().get(0).getMountPath());
    V1Container container = mlJobReplicaSpec.getTemplate().getSpec().getContainers().get(0);
    Assert.assertEquals(AbstractCodeLocalizer.CODE_LOCALIZER_MOUNT_NAME, container.getVolumeMounts().get(0).getName());
    Assert.assertEquals(AbstractCodeLocalizer.CODE_LOCALIZER_PATH, container.getVolumeMounts().get(0).getMountPath());
    for (V1EnvVar env : container.getEnv()) {
        if (env.getName().equals(AbstractCodeLocalizer.CODE_LOCALIZER_PATH_ENV_VAR)) {
            Assert.assertEquals(AbstractCodeLocalizer.CODE_LOCALIZER_PATH, env.getValue());
        }
    }
