/**
 * Test zip function.
 * A dir "/user/yarn/mydir" has two files and one subdir
 */
@Test
public void testYarnServiceSubmitterZipFunction() throws Exception {
    String localUrl = "/user/yarn/mydir";
    String localSubDirName = "subdir1";
    // create local file
    File localDir1 = testCommons.getFileUtils().createDirInTempDir(localUrl);
    testCommons.getFileUtils().createFileInDir(localDir1, "1.py");
    testCommons.getFileUtils().createFileInDir(localDir1, "2.py");
    File localSubDir = testCommons.getFileUtils().createDirectory(localDir1, localSubDirName);
    testCommons.getFileUtils().createFileInDir(localSubDir, "3.py");
    String tempDir = localDir1.getParent();
    String zipFilePath = ZipUtilities.zipDir(localDir1.getAbsolutePath(), new File(tempDir, "mydir.zip").getAbsolutePath());
    File zipFile = new File(zipFilePath);
    File unzipTargetDir = new File(tempDir, "unzipDir");
    FileUtil.unZip(zipFile, unzipTargetDir);
    assertTrue(new File(tempDir + "/unzipDir/1.py").exists());
    assertTrue(new File(tempDir + "/unzipDir/2.py").exists());
    assertTrue(new File(tempDir + "/unzipDir/subdir1").exists());
    assertTrue(new File(tempDir + "/unzipDir/subdir1/3.py").exists());
}

